// workspace-material.mjs — Material: the project's readers, recorded files and THE ONE
// shared-material mount (M5 C9). Also the storage panel and the saved-turn inspector panel.
// Ownership: /work/materials (recorded files, paged 20, coverage sentence), /projects/
//   material-references (shared bindings: list, preview, source, attach/adopt/remove),
//   /work/storage and /work/storage/prune (explicit request only), /authoring/session-turn
//   (saved turn), /authoring/state view=sessions (turn catalogue).
// Presentation: readers as relation rows (only available readers are doors); recorded files as
//   cards with an availability chip (Recorded / Missing), Read as the primary action, Discuss
//   and history; shared bindings with a currentness chip (Current / Owner changed / Owner
//   unavailable / Not linked) whose title is the owner sentence; Inspect, Adopt, Remove.
// Public contract: mountMaterial(host,{project,info,request,onShow,onArtifact,onHistory,
//   onDiscuss,projects,draft,selectedBinding,onInspectOwner,pending (the shell's V9 pending-read helper)});
//   mountSharedReferences;
//   mountStorage; openSavedTurn; mountTurns; workspaceViewAvailable; terminalWork;
//   taskPrerequisites; artifactReaderOptions; readableBytes.
// Retired (C2/C9): the project Dependencies view; view=dependencies is an alias that opens
//   Material at its shared bindings; workspace-wide dependencies stay in workspace-app.mjs.
// Storage: none.
import {inspectRecoveryRead} from './workspace-analytics.mjs';
import {sharedInspector,replacedByInspector} from './workspace-inspector.mjs';
import {renderMaterialObservation} from './workspace-material-observation.mjs';
import {turnFailures,appendSavedRecovery,artifactHumanTarget} from './workspace-session.mjs';
import {renderParentContinuation} from './prepared-work.mjs';
import {chipRow,lazySection,relationList,stateChip,declareControl} from './workspace-presentation.mjs';
import {pendingRead} from './pending-read.mjs';
// Project views are adapters over canonical owners, never stored workspace truth.
const el=(tag,text='',cls='')=>{const node=document.createElement(tag);node.textContent=text;node.className=cls;return node;};
const url=(path,data)=>path+'?'+new URLSearchParams(data);
const action=(label,run,enabled=()=>true)=>{const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;try{await run();}catch(error){const note=el('p',error.message,'error');note.setAttribute('role','alert');b.after(note);}finally{b.disabled=!enabled();}};return b;};
// SOURCES ROWS (wave 5). A source is one row: its name on one line, the owner's state words as text, its main action
// and its other content behind labelled controls. The name is cut in the middle when the row is too narrow (the start
// ends in an ellipsis; the last characters, the file's own ending, stay) and the whole text is in the title attribute.
const sourceName=text=>{const node=el('h4','','material-name');node.title=text;const tail=text.length>32?16:0;node.append(el('span',tail?text.slice(0,-tail):text,'material-name-start'));if(tail)node.append(el('span',text.slice(-tail),'material-name-end'));return node;};
// the owner's state words as text, each with its owner sentence as the title; the tone colours a word, never replaces it
const stateWords=chips=>{const line=el('span','','material-state-words');chips.filter(Boolean).forEach((chip,index)=>{if(index)line.append(el('span',' · '));const word=el('span',chip.label,'material-state-word');word.dataset.tone=chip.tone||'neutral';if(chip.title)word.title=chip.title;line.append(word);});return line;};
// a row's secondary content: one labelled control (the shell's disclosure, drawn with Show / Hide in words) whose panel
// opens in place under the row, across the row's whole width
const rowDisclosure=(label,kind,panel,control)=>{const details=el('details','','material-disclosure '+kind);details.append(declareControl(el('summary',label),control));panel.className='material-row-panel '+kind+'-panel';panel.hidden=true;details.ontoggle=()=>{panel.hidden=!details.open;};return details;};
// what the row's former identity control opened is one small heading inside the row's single panel, in the same words
const identityPart=(heading,lines)=>{const part=el('section','','material-identity-part material-identity');part.append(el('h5',heading,'material-identity-heading'),...lines);return part;};
// Read's visible label is short (the name is already on the row); its accessible name and title still carry the name
const readControl=(name,run)=>{const read=declareControl(action('Read',run),'material:read',name);read.append(el('span',' '+name,'sr-only'));read.classList?.add?.('primary');read.title='Read '+name;return read;};
export const terminalWork=task=>['done','verified','cancelled'].includes(task.status);
export function taskPrerequisites(tasks=[]){const index=new Map(tasks.map(row=>[row.id,row]));return tasks.filter(row=>row.depends_on?.length).map(row=>({task:row,prerequisites:row.depends_on.map(id=>({id,title:index.get(id)?.title||id,status:index.get(id)?.status||'unavailable'}))}));}
export function turnObservation(turn,active=null){if(active?.id===turn.id)return 'Active turn reported by the execution owner';if(turn.reply)return 'Saved reply · work completion is separate';return 'No final reply recorded · execution status unknown';}
// A recorded-file row opens through its OWNER-ISSUED receipt route (owner=writing-artifact, artifact_id, scope, pin):
// the same human_read read_artifact issues, so a manuscript-scoped artifact is read beside the selected draft and never
// through another home's same-named file. The route is used only when it names this row's receipt and pin. Every
// other row still opens through the writing-artifact owner (never a bare Research path): with its exact receipt id and
// complete pin when it has both; with its receipt id and NO pin when the receipt recorded none or a malformed one (the
// owner then reads the current bytes at the receipt's exact path and says the historical identity is unavailable);
// with owner, path, scope (and its pin, if recorded) for a History activity that has no receipt id.
const completePin=value=>typeof value==='string'&&/^(?:sha256:)?[a-fA-F0-9]{64}$/.test(value)?value.replace(/^sha256:/,'').toLowerCase():null;
export function artifactReaderOptions(row,{project}={}){
  const receipt=typeof row.id==='string'&&/^ART-[a-zA-Z0-9-]+$/.test(row.id)?row.id:null,pin=completePin(row.recorded_revision);
  const target=row.human_read?.url&&project?artifactHumanTarget(row.human_read.url,{project}):null;
  const notice=receipt?(pin?'Recorded receipt '+receipt+'. Current bytes must match this revision; use History for earlier retained content.':
      'Receipt '+receipt+' recorded no byte identity, so its historical revision is unavailable. This shows the current file at the receipt\'s exact path.'):
    pin?'Recorded artifact revision; the reader checks its pin.':'No recorded receipt or revision is attached to this activity; this shows the current file.';
  if(receipt&&pin&&target&&target.artifactId===receipt&&target.scope===row.scope&&completePin(target.expectedSha256)===pin)return {...target,notice};
  return {...(row.path?{path:row.path}:{}),scope:row.scope,artifactOwner:'writing-artifact',notice,
    ...(receipt?{artifactId:receipt}:{}),...(pin?{expectedSha256:pin}:{})};
}

// Identity-qualified Material: a linked reference and a recorded file are the SAME material only when owner, project,
// scope, path AND revision all agree. A shared path alone never deduplicates; both records keep their own history and guarantees.
export function sameMaterialIdentity(reference,row,{project}={}){const t=reference?.target||{},pin=v=>typeof v==='string'&&/^(?:sha256:)?[a-fA-F0-9]{64}$/.test(v)?v.replace(/^sha256:/,'').toLowerCase():null;
  if(t.owner!=='artifact'||t.project!==project||t.scope!==row?.scope||t.path!==row?.path)return false;const a=pin(reference.consumed_revision),b=pin(row?.recorded_revision);return !!a&&a===b;}
export function workspaceViewAvailable(info={},view){
  const keys={work:'work',material:'materials',turns:'turns',history:'history',settings:'settings',structure:'concepts',argument:'concepts','reader-plan':'reader_plan',research:'research',manuscript:'manuscript',review:'review',presentation:'presentation'};
  if(view==='overview')return true;
  const cap=info.capabilities?.[keys[view]];
  return ['work','material','turns','history','settings'].includes(view)?cap!==false:cap===true;
}
const referenceState=row=>({CURRENT:'Consumed revision is current',CHANGED_INPUT:'Owner changed · consumed revision retained',UNRESOLVED:'Owner unavailable · consumed revision retained',UNBOUND:'Inspected owner content · not linked'}[row.currentness]||'Currentness unavailable');
// chips replace prose (M5 C9): the owner's currentness word with the sentence as its title
const referenceChip=row=>({label:({CURRENT:'Current',CHANGED_INPUT:'Owner changed',UNRESOLVED:'Owner unavailable',UNBOUND:'Not linked'})[row.currentness]||'Currentness unavailable',tone:({CURRENT:'ok',CHANGED_INPUT:'attention',UNRESOLVED:'blocked',UNBOUND:'neutral'})[row.currentness]||'neutral',title:referenceState(row)});
const addRetainedLiterature=async(project,read,request,isCurrent)=>{const {openRetainedSourceLiterature}=await import('./retained-source-literature.mjs');if(isCurrent())return openRetainedSourceLiterature({project,read,request,isCurrent});};
const referenceURL=(project,fields={})=>url('/projects/material-references',{project,...fields,...(fields.target?{target:JSON.stringify(fields.target)}:{})});

