  if(onAddLocalDocument){const add=el('button','Add local document');add.type='button';add.dataset.control='material:add-document';let opening=false;add.onclick=async()=>{if(opening)return;opening=true;try{await onAddLocalDocument();}catch(error){const note=el('p',error.message,'error');note.setAttribute('role','alert');pageActions.after(note);}finally{opening=false;}};pageActions.append(add);}
  if(onRefresh)pageActions.append(declareControl(action('Refresh sources',onRefresh),'material:refresh-sources'));
  // readers as relation rows (M5 C9): each reader is a door to its view; absence is a sentence
  const readers=el('details','','material-readers material-disclosure');readers.append(declareControl(el('summary','Other project reading views'),'material:readers'));
  if(!workspaceViewAvailable(info,'manuscript'))readers.append(el('p',info.source_optional?'A manuscript is optional. Work and shared material are available.':'No manuscript is selected. Project work and recorded material remain available.','muted'));
  const readerRows=[['manuscript','Manuscript','Reader'],['research','Research & sources','Reader'],['review','Review changes','Reader'],['presentation','Figures & output','Reader']].filter(([view])=>workspaceViewAvailable(info,view)).map(([view,label,kind])=>({kind,label,run:()=>onShow(view),control:'material:reader',owner:view}));
  const readerList=relationList(readerRows,{emptyText:'No readers are available for this project.'});readerList.setAttribute('data-control','material:reader');readers.append(readerList);
